insert into public.exercises (owner_id, name, main_muscles, purpose, form_instructions, common_mistakes, alternatives, video_url, is_timed, source)
values
  (null, 'Lat pulldown', 'Latissimus dorsi; biceps; upper-back stabilisers', 'Back width; vertical pulling strength', 'Set thighs under pads; use a comfortable grip; brace torso with a slight lean; pull bar toward upper chest by driving elbows down; return slowly to a controlled stretch.', 'Don''t pull behind neck, swing, or turn it into a row. Keep wrists neutral.', 'Assisted pull-up; single-arm kneeling cable pulldown; resistance-band pulldown.', 'https://www.youtube.com/results?search_query=lat+pulldown+proper+form', false, 'curated'),
  (null, 'Chest-supported row', 'Rhomboids, mid traps, lats; rear delts; biceps', 'Mid-back thickness with less lower-back loading', 'Set chest firmly against pad; start with arms extended; row elbows back; pause briefly; lower under control.', 'Avoid shrugging, bouncing chest off pad, or overextending elbows.', 'Incline-bench dumbbell row; seated cable row; one-arm dumbbell row with support.', 'https://www.youtube.com/results?search_query=chest+supported+row+proper+form', false, 'curated'),
  (null, 'Single-arm cable lat pulldown', 'Lats; teres major; biceps', 'Unilateral lat focus and shoulder extension', 'Set pulley high; reach up comfortably; pull elbow down toward same-side hip; keep torso quiet; return slowly.', 'Avoid twisting or leaning heavily; don''t pull with wrist only.', 'Single-arm kneeling band pulldown; one-arm dumbbell pullover.', 'https://www.youtube.com/results?search_query=single+arm+cable+lat+pulldown+proper+form', false, 'curated'),
  (null, 'Reverse pec deck', 'Rear deltoids; mid traps; rhomboids', 'Rear shoulder and upper-back balance', 'Face pad; set handles around shoulder height; keep soft elbows; open arms out; pause; return slowly.', 'Don''t shrug or use momentum; avoid forcing arms far behind torso.', 'Bent-over dumbbell reverse fly; cable rear-delt fly; band pull-apart.', 'https://www.youtube.com/results?search_query=reverse+pec+deck+proper+form', false, 'curated'),
  (null, 'Incline dumbbell curl', 'Biceps brachii (long head emphasis); brachialis', 'Biceps size through a lengthened position', 'Set bench to a moderate incline; let arms hang naturally; keep upper arms mostly still; curl without swinging; lower slowly.', 'Don''t let shoulders roll forward or elbows drift forward excessively.', 'Bayesian cable curl; standing alternating dumbbell curl; preacher curl.', 'https://www.youtube.com/results?search_query=incline+dumbbell+curl+proper+form', false, 'curated'),
  (null, 'Hammer curl', 'Brachialis; brachioradialis; biceps', 'Arm thickness and forearm contribution', 'Hold dumbbells with palms facing each other; keep elbows near sides; curl smoothly; lower under control.', 'Avoid torso swing or wrist bending.', 'Rope cable hammer curl; cross-body hammer curl; resistance-band hammer curl.', 'https://www.youtube.com/results?search_query=dumbbell+hammer+curl+proper+form', false, 'curated'),
  (null, 'Incline dumbbell press', 'Upper pectoralis major; anterior deltoids; triceps', 'Upper chest development', 'Set bench around 20–30°; feet planted; shoulder blades gently set; lower dumbbells to upper chest with forearms near vertical; press smoothly.', 'Avoid very steep bench angle, bouncing, or excessive lower-back arch.', 'Incline machine press; incline barbell press; feet-stable push-up with hands elevated (if no bench).', 'https://www.youtube.com/results?search_query=incline+dumbbell+press+proper+form', false, 'curated'),
  (null, 'Seated shoulder press', 'Anterior and lateral deltoids; triceps', 'Shoulder pressing strength and mass', 'Use back support; start around shoulder level; brace trunk; press overhead in a comfortable path; lower with control.', 'Don''t flare ribs or overarch lower back; don''t force painful range.', 'Dumbbell shoulder press; landmine press; machine shoulder press.', 'https://www.youtube.com/results?search_query=seated+shoulder+press+proper+form', false, 'curated'),
  (null, 'Machine chest press', 'Pectoralis major; anterior deltoids; triceps', 'Chest pressing volume', 'Adjust seat so handles align around mid-chest; keep back supported; press smoothly; return until comfortable chest stretch.', 'Don''t let shoulders roll forward or slam weight stack.', 'Dumbbell flat bench press; push-ups; Smith-machine bench press.', 'https://www.youtube.com/results?search_query=machine+chest+press+proper+form', false, 'curated'),
  (null, 'Cable lateral raise', 'Lateral deltoids; supraspinatus', 'Shoulder width / side-delt emphasis', 'Set pulley low; stand side-on; raise arm slightly forward of body to about shoulder height; keep soft elbow; lower slowly.', 'Use modest load; avoid swinging and shrugging; stop if painful.', 'Dumbbell lateral raise; lateral-raise machine; leaning-away dumbbell lateral raise.', 'https://www.youtube.com/results?search_query=cable+lateral+raise+proper+form', false, 'curated'),
  (null, 'Rope triceps pushdown', 'Triceps brachii (all heads)', 'Triceps size and elbow extension', 'Stand tall; elbows close to sides; extend forearms down; separate rope ends slightly; return slowly without upper-arm movement.', 'Avoid leaning bodyweight onto rope or letting elbows travel forward/back.', 'Straight-bar pushdown; resistance-band pushdown; close-grip push-up.', 'https://www.youtube.com/results?search_query=rope+triceps+pushdown+proper+form', false, 'curated'),
  (null, 'Overhead cable triceps extension', 'Triceps brachii, long head emphasis', 'Triceps long-head work in an overhead position', 'Face away from high pulley or use rope overhead; brace trunk; keep upper arms relatively fixed; bend elbows for stretch; extend smoothly.', 'Don''t flare elbows excessively or arch lower back; use pain-free range.', 'Seated overhead dumbbell extension; single-dumbbell overhead extension; band overhead extension.', 'https://www.youtube.com/results?search_query=overhead+cable+triceps+extension+proper+form', false, 'curated'),
  (null, 'Leg press (or squat)', 'Quadriceps; gluteus maximus; adductors', 'Thigh and glute strength', 'Set feet about shoulder-width; lower platform until thighs approach comfortable depth while pelvis stays stable; press through whole foot.', 'Don''t let knees collapse inward or lower back round/lift; avoid locking knees hard.', 'Goblet squat; hack squat; bodyweight split squat; barbell squat if trained and comfortable.', 'https://www.youtube.com/results?search_query=leg+press+proper+form', false, 'curated'),
  (null, 'Romanian deadlift', 'Hamstrings; gluteus maximus; spinal erectors isometrically', 'Posterior chain and hip-hinge strength', 'Hold bar/dumbbells close; soften knees; push hips back; keep spine neutral; lower until hamstrings stretch; stand by driving hips forward.', 'It''s a hip hinge, not a squat; don''t round back or chase floor depth.', 'Dumbbell RDL; cable pull-through; 45-degree hip extension with hip hinge.', 'https://www.youtube.com/results?search_query=Romanian+deadlift+proper+form', false, 'curated'),
  (null, 'Seated leg curl', 'Hamstrings', 'Hamstring knee-flexion strength', 'Align knee with machine pivot; adjust pad; keep hips down; curl smoothly; pause; return slowly.', 'Don''t lift hips or use momentum; control the eccentric.', 'Lying leg curl; standing single-leg curl; stability-ball leg curl.', 'https://www.youtube.com/results?search_query=seated+leg+curl+proper+form', false, 'curated'),
  (null, 'Standing calf raise', 'Gastrocnemius; soleus', 'Calf strength and size', 'Use full comfortable range; lower heel for stretch; rise onto ball of foot; pause at top; lower slowly.', 'Avoid bouncing or rolling ankles; keep knees softly extended.', 'Dumbbell calf raise on step; leg-press calf raise; single-leg bodyweight calf raise.', 'https://www.youtube.com/results?search_query=standing+calf+raise+proper+form', false, 'curated'),
  (null, 'Cable crunch', 'Rectus abdominis; obliques as stabilisers', 'Trunk flexion / abdominal strength', 'Kneel facing cable; rope by temples; curl ribs toward pelvis; keep hips mostly fixed; return slowly.', 'Don''t hinge only at hips or yank with arms; exhale during curl.', 'Weighted floor crunch; machine abdominal crunch; reverse crunch.', 'https://www.youtube.com/results?search_query=kneeling+cable+crunch+proper+form', false, 'curated'),
  (null, 'Side plank', 'Obliques; transverse abdominis; quadratus lumborum; glute medius', 'Lateral core stability', 'Elbow under shoulder; stack or stagger feet; lift hips; keep head, trunk and hips aligned; breathe steadily.', 'Don''t let hips sag or rotate; use bent-knee version if needed.', 'Side plank from knees; suitcase carry; Pallof press.', 'https://www.youtube.com/results?search_query=side+plank+proper+form', true, 'curated'),
  (null, 'Medium-wide overhand lat pulldown', 'Lats; teres major; biceps', 'Back width / vertical pulling', 'Use a comfortable grip just outside shoulder width; slight stable lean; pull to upper chest; drive elbows down; control return.', 'Extremely wide grip isn''t necessary; don''t pull behind neck or swing.', 'Assisted pull-up; neutral-grip pulldown; single-arm kneeling cable pulldown.', 'https://www.youtube.com/results?search_query=medium+wide+grip+lat+pulldown+proper+form', false, 'curated'),
  (null, 'Seated cable row (neutral grip)', 'Mid traps; rhomboids; lats; rear delts; biceps', 'Mid-back thickness and scapular control', 'Sit tall; brace; pull handle toward lower ribs; draw elbows back; pause; extend arms without rounding lower back.', 'Avoid rocking torso or shrugging; don''t over-pull past torso.', 'Chest-supported dumbbell row; machine row; resistance-band row.', 'https://www.youtube.com/results?search_query=seated+cable+row+neutral+grip+proper+form', false, 'curated'),
  (null, 'Straight-arm cable pulldown', 'Lats; teres major; long head of triceps assists', 'Lat isolation / shoulder extension', 'Set cable high; slight hip hinge; elbows softly bent; sweep bar/rope toward thighs; keep trunk steady; return under control.', 'Don''t turn it into a triceps pressdown or round shoulders forward.', 'Dumbbell pullover; resistance-band straight-arm pulldown; machine pullover.', 'https://www.youtube.com/results?search_query=straight+arm+cable+pulldown+proper+form', false, 'curated'),
  (null, 'Cable or machine lateral raise', 'Lateral deltoids; supraspinatus', 'Shoulder width emphasis', 'Raise upper arms out and slightly forward to around shoulder height; use light-moderate load; lower slowly.', 'Don''t shrug, swing or lift through pain; control each rep.', 'Dumbbell lateral raise; leaning cable lateral raise; partial lateral raise with light dumbbells.', 'https://www.youtube.com/results?search_query=cable+lateral+raise+proper+form', false, 'curated'),
  (null, 'Incline machine chest press', 'Upper pectoralis major; anterior deltoids; triceps', 'Upper chest stimulus', 'Set seat so handles start around upper/mid chest; shoulder blades supported; press smoothly; lower to comfortable stretch.', 'Avoid excessively high seat/shoulder discomfort or locking elbows hard.', 'Incline dumbbell press; incline barbell press; feet-elevated push-up if appropriate.', 'https://www.youtube.com/results?search_query=incline+machine+chest+press+proper+form', false, 'curated'),
  (null, 'Moderate cardio', 'Cardiorespiratory system; lower body depending on mode', 'Aerobic fitness and recovery support', 'Choose incline treadmill, bike or elliptical; maintain a pace where you can speak in sentences; 25–35 minutes.', 'Don''t turn it into an all-out interval session; adjust for fatigue and joint comfort.', 'Outdoor brisk walk; stationary bike; elliptical; swimming at moderate effort.', 'https://www.youtube.com/results?search_query=moderate+intensity+cardio+talk+test', true, 'curated'),
  (null, 'EZ-bar curl', 'Biceps brachii; brachialis', 'Biceps size and strength', 'Stand tall; grip comfortable angled sections; keep elbows near sides; curl without swing; lower slowly.', 'Avoid hip drive and wrist discomfort; use a load you can control.', 'Dumbbell curl; cable curl; resistance-band curl.', 'https://www.youtube.com/results?search_query=EZ+bar+biceps+curl+proper+form', false, 'curated')
